DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_CRISTIANORONALDO' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_1','The Relentless Seven[NEWLINE]Preserved military veterans and a seven-chapter career[NEWLINE]Domination or Culture; Diplomacy as a secondary route[NEWLINE][NEWLINE]Develop military experience, survive genuine upgrades and earn Ambition through several achievement types. Reinvention rewards a unit''s own career; buying an advanced replacement does not recreate the veteran that was lost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_2','Build a real defensive army and Sporting Academies in worthwhile training cities. Fight controlled battles, keep promotion candidates alive, and support ordinary Culture and economic development.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_3','Save Gold for genuine upgrades and pursue achievable Ambition sources alongside combat. Let ranged units soften targets before valuable finishers attack. Read both chapter progress and the current Reinvention cap before planning around a later unlock.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_4','Use upgraded veterans and permanent career benefits for a focused campaign or a stronger cultural economy. Keep the capital and support cities functioning; experience and kill healing are valuable only on units that survive the enemy''s full turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_5','- Combat XP and genuine upgrades reward long-lived armies.[NEWLINE]- Several military and peaceful achievements contribute Ambition.[NEWLINE]- Reinvention combines bounded permanent strength with healing on kills.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_6','- Lost veterans cannot be replaced with their accumulated career history.[NEWLINE]- Reinvention has a chapter-dependent cap.[NEWLINE]- Several rewards require genuine combat, production or birth events rather than arbitrary creation or repeated manipulation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_7','- Focus a valuable veteran to completion instead of spreading damage across heal-on-kill targets.[NEWLINE]- Deny easy wounded-unit finishes and force expensive upgrade choices.[NEWLINE]- Apply pressure before the later chapters and avoid feeding a long sequence of successful engagements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_8','- Expecting a newly built advanced unit to receive earlier Reinvention tiers.[NEWLINE]- Treating every conversion or promotion change as a genuine upgrade.[NEWLINE]- Taking a risky extra kill when retreat would preserve an irreplaceable veteran.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Developed finishers can end an exchange before a climber safely completes its repeated Project attacks.[NEWLINE][NEWLINE]The Urgal: A preserved army can exploit Aftertaste after surviving the potion window; it should not trade unsupported into the full attack bonus.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]T1: A very long-lived, repeatedly upgraded T1 roster can keep developing beyond Ronaldo''s bounded Reinvention strength tiers.[NEWLINE][NEWLINE]The Filthy Realm: A timed movement/attack shutdown can expose the concentrated veterans that the career depends on preserving.');
