INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_LEADER_BACKGROUND','Develop military experience, survive genuine upgrades and earn Ambition through several achievement types. Reinvention rewards a unit''s own career; buying an advanced replacement does not recreate the veteran that was lost.');
