INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_STRATEGY','Develop military experience, survive genuine upgrades and earn Ambition through several achievement types. Reinvention rewards a unit''s own career; buying an advanced replacement does not recreate the veteran that was lost.[NEWLINE][NEWLINE]Build a real defensive army and Sporting Academies in worthwhile training cities. Fight controlled battles, keep promotion candidates alive, and support ordinary Culture and economic development.[NEWLINE][NEWLINE]Save Gold for genuine upgrades and pursue achievable Ambition sources alongside combat. Let ranged units soften targets before valuable finishers attack. Read both chapter progress and the current Reinvention cap before planning around a later unlock.[NEWLINE][NEWLINE]Use upgraded veterans and permanent career benefits for a focused campaign or a stronger cultural economy. Keep the capital and support cities functioning; experience and kill healing are valuable only on units that survive the enemy''s full turn.');
