INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_LEADER_TEXT_1','The Relentless Seven[NEWLINE]Preserved military veterans and a seven-chapter career[NEWLINE]Domination or Culture; Diplomacy as a secondary route[NEWLINE][NEWLINE]Develop military experience, survive genuine upgrades and earn Ambition through several achievement types. Reinvention rewards a unit''s own career; buying an advanced replacement does not recreate the veteran that was lost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_LEADER_TEXT_2','Build a real defensive army and Sporting Academies in worthwhile training cities. Fight controlled battles, keep promotion candidates alive, and support ordinary Culture and economic development.[NEWLINE][NEWLINE]Save Gold for genuine upgrades and pursue achievable Ambition sources alongside combat. Let ranged units soften targets before valuable finishers attack. Read both chapter progress and the current Reinvention cap before planning around a later unlock.[NEWLINE][NEWLINE]Use upgraded veterans and permanent career benefits for a focused campaign or a stronger cultural economy. Keep the capital and support cities functioning; experience and kill healing are valuable only on units that survive the enemy''s full turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CRISTIANORONALDO_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Developed finishers can end an exchange before a climber safely completes its repeated Project attacks.[NEWLINE][NEWLINE]The Urgal: A preserved army can exploit Aftertaste after surviving the potion window; it should not trade unsupported into the full attack bonus.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]T1: A very long-lived, repeatedly upgraded T1 roster can keep developing beyond Ronaldo''s bounded Reinvention strength tiers.[NEWLINE][NEWLINE]The Filthy Realm: A timed movement/attack shutdown can expose the concentrated veterans that the career depends on preserving.');
